Lemma MBuf_transport_gen : forall W m m' b es insz,
  MBuf m b es insz -> munch W m m' -> wmono rsegs m m' ->
  disjoint_from W b 64 -> (forall x s, In (x, s) es -> disjoint_from W x (24 + s)) ->
  MBuf m' b es insz.
Proof. intros W m m' b es insz [R OK] MU WM DB DE. split; [| exact OK]. eapply MBraw_transport_gen; eauto. Qed.

(* [comment removed for export] *)
Lemma MBufOwn_client : forall LB SP b es insz m x s,
  MBuf m b es insz -> MBufOwn LB es -> In (x, s) es -> rclient_range LB SP x (24 + s).
Proof.
  intros LB SP b es insz m x s [(ls & _ & _ & _ & _ & _ & AOK) OK] OWN IN.
  destruct (OWN x s IN) as [p INB]. pose proof AOK as (AD & _). destruct (AD x s IN) as (_ & _ & S0 & _).
  pose proof (mb_block_size_range s S0) as [RS _].
  right; right. exists (p, x, mb_block_size s). split; [exact INB|]. unfold blk_addr, blk_size; cbn. lia.
Qed.
