Lemma MBuf_xpres : forall LB SP X m m' b es insz,
  MBuf m b es insz -> MBufOwn LB es -> xpres LB SP X m m' -> SP <= b ->
  Forall (fun iv : Z * Z => b + 64 <= fst iv \/ snd iv <= b) X ->
  (forall x s, In (x, s) es -> Forall (fun iv : Z * Z => x + 24 + s <= fst iv \/ snd iv <= x) X) ->
  MBuf m' b es insz.
Proof. intros LB SP X m m' b es insz [R OK] OWN XP LE XB XE. split; [| exact OK]. eapply MBraw_xpres; eauto. Qed.

(* [comment removed for export] *)
Lemma mb_elemsW_Forall_sep : forall (es' : list mbe) A k,
  (forall x s, In (x, s) es' -> A + k <= x \/ x + 24 + s <= A) ->
  Forall (fun iv : Z * Z => A + k <= fst iv \/ snd iv <= A) (mb_elemsW es').
Proof.
  intros es' A k D. induction es' as [|[x s] es' IH]; cbn; [constructor|].
  constructor. { cbn. apply (D x s). left; reflexivity. }
  apply IH. intros x' s' IN. apply (D x' s'). right. exact IN.
Qed.

